Appointment Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(appointment_service, "Appointment Service") {
    Component(appointment_api_controller, "Appointment API Controller", "Node.js / Go", "Handles incoming API requests for appointments and invokes core domain logic.")
    Component(scheduling_engine, "Scheduling Engine", "Node.js / Go", "Executes core domain logic, resource clash checks, and atomic writes.")
    Component(waitlist_manager, "Waitlist Manager", "Node.js / Go", "Manages waitlists and handles slot-freed events.")
    Component(notification_publisher, "Notification Publisher", "Node.js / Go", "Publishes domain events and analytics tags to messaging infrastructure.")
}

Rel(appointment_api_controller, scheduling_engine, "Invokes core domain logic", "In-Process")
Rel(scheduling_engine, notification_publisher, "Publishes domain events and analytics tags", "Kafka Producer")
Rel(notification_publisher, waitlist_manager, "Triggers slot-freed events", "In-Process / Event Handler")

@enduml

HL7 FHIR Interoperability Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(hl7_fhir_interoperability_service, "HL7 FHIR Interoperability Service") {
    Component(FHIR API Router, "FHIR API Router", "Python / FastAPI", "Routes incoming RESTful API requests and enforces mTLS security policies.")
    Component(Pydantic Schema Validator, "Pydantic Schema Validator", "Pydantic", "Performs strict runtime data validation against HL7 FHIR resource schemas.")
    Component(External Lab Integration Client, "External Lab Integration Client", "Python HTTP Client / mTLS", "Handles outbound communication with External Lab & Imaging Systems using HL7 FHIR APIs.")
}

Rel(FHIR API Router, Pydantic Schema Validator, "Validates incoming request payloads")
Rel(FHIR API Router, External Lab Integration Client, "Dispatches authenticated FHIR requests")
@enduml

Apache Kafka.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(apache_kafka, "Apache Kafka") {
    Component(Kafka_Brokers, "Kafka Brokers", "Apache Kafka", "Handles event streaming and message transport across microservices.")
    Component(KRaft_Quorum, "KRaft Quorum", "Apache Kafka KRaft", "Manages metadata and consensus without relying on ZooKeeper.")
    Component(Schema_Registry, "Schema Registry", "Confluent Schema Registry", "Enforces data governance using Avro and Protobuf schemas.")
    Component(Kafka_Connect_Sink, "Kafka Connect Sink", "Kafka Connect", "Streams encrypted data from Kafka to S3/MinIO Object Storage via HTTPS.")
}

Rel(Kafka_Brokers, Schema_Registry, "Streams data to and validates against", "Avro/Protobuf")
Rel(Kafka_Brokers, Kafka_Connect_Sink, "Sends event data to", "Kafka protocol")

@enduml
